<?php
declare(strict_types=1);require_once dirname(__DIR__).'/config/bootstrap.php';require_permission('purchases.pay');$id=(int)($_GET['id']??0);$st=db()->prepare('SELECT p.*,s.name supplier_name FROM purchases p INNER JOIN suppliers s ON s.id=p.supplier_id WHERE p.id=:id');$st->execute([':id'=>$id]);$p=$st->fetch();if(!$p||$p['status']==='cancelled'){flash('error','Purchase is unavailable.');redirect('purchases/index.php');}$methods=db()->query('SELECT id,name,method_type,requires_reference FROM payment_methods WHERE is_active=1 AND method_type<>"credit" ORDER BY sort_order,name')->fetchAll();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){require_valid_csrf();try{$amount=money_to_cents((string)($_POST['amount']??'0'));$balance=money_to_cents($p['balance_due']);if($amount<=0||$amount>$balance)throw new RuntimeException('Payment must be greater than zero and not exceed the balance.');}catch(Throwable$e){$errors[]=$e->getMessage()?:'Enter a valid payment amount.';$amount=0;}$methodId=(int)($_POST['payment_method_id']??0);$reference=trim((string)($_POST['reference_no']??''));$method=payment_method_by_id(db(),$methodId);if(!$method||$method['method_type']==='credit')$errors[]='Choose a valid payment method.';elseif((int)$method['requires_reference']===1&&$reference==='')$errors[]='Enter the payment reference.';
if(!$errors){$pdo=db();try{$pdo->beginTransaction();$lock=$pdo->prepare('SELECT amount_paid,balance_due,total_amount FROM purchases WHERE id=:id FOR UPDATE');$lock->execute([':id'=>$id]);$fresh=$lock->fetch();$freshBalance=money_to_cents($fresh['balance_due']);if($amount>$freshBalance)throw new RuntimeException('Payment exceeds the current balance.');$newPaid=money_to_cents($fresh['amount_paid'])+$amount;$newBalance=$freshBalance-$amount;$status=$newBalance===0?'paid':'partial';$pay=$pdo->prepare('INSERT INTO purchase_payments(purchase_id,payment_method_id,amount,reference_no,paid_at,created_by) VALUES(:purchase,:method,:amount,:ref,NOW(),:user)');$pay->execute([':purchase'=>$id,':method'=>$methodId,':amount'=>cents_to_decimal($amount),':ref'=>$reference?:null,':user'=>(int)current_user()['id']]);$up=$pdo->prepare('UPDATE purchases SET amount_paid=:paid,balance_due=:balance,payment_status=:status WHERE id=:id');$up->execute([':paid'=>cents_to_decimal($newPaid),':balance'=>cents_to_decimal($newBalance),':status'=>$status,':id'=>$id]);if($method['method_type']==='cash'){$cm=$pdo->prepare('INSERT INTO cash_movements(cash_session_id,branch_id,movement_type,reference_type,reference_id,amount,description,created_by) VALUES(:session,:branch,"cash_out","purchase",:id,:amount,:description,:user)');$cm->execute([':session'=>active_cash_session_id($pdo,(int)current_user()['id'],(int)$p['branch_id']),':branch'=>(int)$p['branch_id'],':id'=>$id,':amount'=>cents_to_decimal(-$amount),':description'=>'Purchase payment '.$p['purchase_no'],':user'=>(int)current_user()['id']]);}$pdo->commit();audit_log('purchase_payment','purchases',$id,'Purchase payment recorded for '.$p['purchase_no'].'.',null,['amount'=>cents_to_decimal($amount),'method'=>$method['name']]);flash('success','Purchase payment recorded.');redirect('purchases/view.php?id='.$id);}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();$errors[]='Payment could not be recorded.';error_log('Purchase payment failed: '.$e->getMessage());}}}
$pageTitle='Purchase Payment';$pageStyles=['admin.css','commerce.css'];require BASE_PATH.'/includes/header.php';require BASE_PATH.'/includes/sidebar.php';?>
<div class="app-main"><?php require BASE_PATH.'/includes/navbar.php';?><main class="content"><div class="narrow-page"><div class="page-toolbar"><div><a class="back-link" href="<?=e(app_url('purchases/view.php?id='.$id))?>">← Purchase</a><h2>Record payment</h2><p><?=e($p['supplier_name'])?> · balance <?=e(money($p['balance_due']))?></p></div></div><?php foreach($errors as$er):?><div class="app-alert app-alert--danger"><?=e($er)?></div><?php endforeach;?><form method="post" class="form-card"><?=csrf_field()?><div class="form-section"><div class="form-grid"><div class="field field--span-2"><label>Amount</label><input type="number" name="amount" min="0.01" max="<?=e($p['balance_due'])?>" step="0.01" value="<?=e($p['balance_due'])?>" required></div><div class="field"><label>Payment method</label><select name="payment_method_id" required><option value="">Select</option><?php foreach($methods as$m):?><option value="<?=e((string)$m['id'])?>"><?=e($m['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Reference</label><input name="reference_no" maxlength="120"></div></div></div><div class="form-actions"><a class="button button--ghost" href="<?=e(app_url('purchases/view.php?id='.$id))?>">Cancel</a><button class="button button--primary">Record payment</button></div></form></div></main></div><?php require BASE_PATH.'/includes/footer.php';?>
